<?php
require_once __DIR__.'/../includes/functions.php';
$errors=[];$done=false;$categories=[];
try{$categories=db()->query('SELECT id,name FROM business_categories ORDER BY name')->fetchAll();}catch(Throwable $e){}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();
 $name=trim($_POST['business_name']??'');$description=trim($_POST['description']??'');$phone=trim($_POST['phone']??'');$whatsapp=trim($_POST['whatsapp']??'');$email=trim($_POST['email']??'');$address=trim($_POST['address']??'');$city=trim($_POST['city']??'Jos');$website=trim($_POST['website']??'');$category=(int)($_POST['category_id']??0);
 if($name==='')$errors[]='Business name is required.';if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email address.';if($website!==''&&!filter_var($website,FILTER_VALIDATE_URL))$errors[]='Enter a complete website URL, including https://.';
 if(!$errors){try{$pdo=db();$slug=unique_slug($pdo,'businesses',$name);$st=$pdo->prepare("INSERT INTO businesses(category_id,business_name,slug,description,phone,whatsapp,email,address,city,state,website,status) VALUES(?,?,?,?,?,?,?,?,?,'Plateau',?,'pending')");$st->execute([$category?:null,$name,$slug,$description,$phone,$whatsapp,$email,$address,$city,$website]);$done=true;}catch(Throwable $e){$errors[]='We could not submit your listing right now. Please try again.';}}
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>List Your Business | Plateau Digital</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><?php include __DIR__.'/../includes/public_header.php';?><main class="form-shell"><span class="eyebrow">Grow your visibility</span><h1>List your business</h1><p>Submit your business details for review by the Plateau Digital team. Listings are not published until approved.</p><?php if($done):?><div class="submit-success"><h3>Submission received!</h3><p>Thank you. Your business listing is now pending review. Our team will review the details before it appears in the directory.</p><a class="text-link" href="directory.php">Return to the directory</a></div><?php else:?><?php foreach($errors as $error):?><div class="submit-error"><?=e($error)?></div><?php endforeach;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="form-field"><label>Business name *</label><input name="business_name" required maxlength="180" value="<?=e($_POST['business_name']??'')?>"></div><div class="form-field"><label>Category</label><select name="category_id"><option value="0">Choose a category</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=((int)($_POST['category_id']??0)===(int)$c['id'])?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="form-field"><label>Phone number</label><input name="phone" value="<?=e($_POST['phone']??'')?>"></div><div class="form-field"><label>WhatsApp number</label><input name="whatsapp" value="<?=e($_POST['whatsapp']??'')?>"></div><div class="form-field"><label>Email address</label><input type="email" name="email" value="<?=e($_POST['email']??'')?>"></div><div class="form-field"><label>Website (optional)</label><input name="website" placeholder="https://" value="<?=e($_POST['website']??'')?>"></div><div class="form-field"><label>City / town</label><input name="city" value="<?=e($_POST['city']??'Jos')?>"></div><div class="form-field"><label>Street address</label><input name="address" value="<?=e($_POST['address']??'')?>"></div><div class="form-field full"><label>About your business</label><textarea name="description" maxlength="3000"><?=e($_POST['description']??'')?></textarea></div></div><div class="form-note">By submitting, you confirm that these details are accurate and that you are authorised to represent this business.</div><div class="form-actions"><button class="btn" type="submit">Submit business for review</button><a class="text-link" href="directory.php">Cancel</a></div></form><?php endif;?></main><?php include __DIR__.'/../includes/public_footer.php';?></body></html>